import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicStampedReference;

public class Main {
    static void spinOnce(AtomicInteger a) {
        while (true) {
            int cur = a.get();
            if (a.compareAndSet(cur, cur + 1)) return;
        }
    }

    public static void main(String[] args) {
        AtomicInteger v = new AtomicInteger(100);
        int observed = v.get();
        v.compareAndSet(100, 200);
        v.compareAndSet(200, 100);
        boolean fooled = v.compareAndSet(observed, 999);
        System.out.println("naive CAS on A->B->A succeeded : " + fooled + " (value=" + v.get() + ")");

        AtomicStampedReference<Integer> sr = new AtomicStampedReference<>(1, 0);
        Integer ref0 = sr.getReference();
        int stamp0 = sr.getStamp();
        sr.compareAndSet(1, 2, stamp0, stamp0 + 1);
        sr.compareAndSet(2, 1, stamp0 + 1, stamp0 + 2);
        boolean rejected = !sr.compareAndSet(ref0, 99, stamp0, stamp0 + 1);
        System.out.println("stamped CAS rejected the ABA  : " + rejected
                + " (value=" + sr.getReference() + ", stamp=" + sr.getStamp() + ")");

        AtomicStampedReference<Integer> boxed = new AtomicStampedReference<>(1000, 0);
        boolean trap = boxed.compareAndSet(1000, 2000, 0, 1);
        System.out.println("boxed CAS over Integer cache  : " + trap + " (reference mismatch, not value mismatch)");

        AtomicInteger spin = new AtomicInteger();
        for (int i = 0; i < 5; i++) spinOnce(spin);
        System.out.println("hand-written CAS loop total   : " + spin.get());
    }
}
